using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Users;[Authorize(Policy="SuperAdminOnly")]public sealed class IndexModel(OrcaFacilDbContext db):PageModel{public IReadOnlyList<Row>Users{get;private set;}=[];public async Task OnGetAsync(CancellationToken ct)=>Users=await db.Users.AsNoTracking().Where(x=>!x.IsDeleted).OrderBy(x=>x.Name).Select(x=>new Row(x.Id,x.Name,x.Email,x.DocumentNumber??"—",x.Role.ToString(),db.AccountMembers.Count(m=>m.UserId==x.Id&&!m.IsDeleted),x.IsBlocked?"Bloqueado":x.IsActive?"Ativo":"Inativo")).ToListAsync(ct);public sealed record Row(Guid Id,string Name,string Email,string Document,string Role,int Accounts,string Status);}
